import React from 'react';
import PropTypes from 'prop-types';
import { ViewportImplantForm } from '@ohif/ui';
import { IVoxelManager } from '@cornerstonejs/core/types';
import { getPresentTeeth, getMissingTeeth } from './implants';
import { startImplantEdition, getAutomaticPose } from './implants/implantEdition';
import { ImplantData, ImplantModel } from '../types/Panoramic';

const ANATOMY_SEG_ID = 'anatomy';
const IMPLANTS_SEG_ID = 'implants';

// Get implant and missing teeth
const getFlaggedTeeth = (servicesManager: AppTypes.ServicesManager) => {
  const { viewportGridService, segmentationService, panoramicService } = servicesManager.services;

  const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
  const { implants = [], minMaxTissueLayer } =
    panoramicService.getPanoramicState(displaySetUID) ?? {};
  const implantTeeth = implants.map(implant => implant.toothNumber);

  const anatomy = segmentationService.getSegmentation(ANATOMY_SEG_ID);
  if (!anatomy || !minMaxTissueLayer) {
    return { implantTeeth, missingTeeth: [] };
  }
  const { voxelManager } = segmentationService.getLabelmapVolume(ANATOMY_SEG_ID);
  const presentTeeth = getPresentTeeth(
    anatomy.segments,
    voxelManager as IVoxelManager<number>,
    minMaxTissueLayer
  );

  return { implantTeeth, missingTeeth: getMissingTeeth(presentTeeth) };
};

// Tooth selection for a new implant. compact: small version for the side panel, onExpand opens the large one.
const CornerstoneViewportImplantForm = ({
  hide,
  servicesManager,
  commandsManager,
  compact = false,
  onExpand = () => {},
  defaultToothNumber = -1,
  onToothChange,
}: withAppTypes<{
  hide: () => void;
  compact?: boolean;
  onExpand?: () => void;
  defaultToothNumber?: number;
  onToothChange: (toothNumber: number) => void;
}>) => {
  const { implantTeeth, missingTeeth } = getFlaggedTeeth(servicesManager);

  // Compute and save a new implant on the tooth
  const addImplant = async (toothNumber: number, implantModel: ImplantModel) => {
    const { viewportGridService, segmentationService, panoramicService } = servicesManager.services;

    if (!segmentationService.getSegmentation(IMPLANTS_SEG_ID)) {
      return false;
    }

    const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
    const panoramicState = panoramicService.getPanoramicState(displaySetUID);
    const { implants } = panoramicState;

    // Only a new implant is placed automatically
    const exists = implants.some(implant => implant.toothNumber === toothNumber);
    if (!exists) {
      const pose = getAutomaticPose(servicesManager, toothNumber);
      if (!pose) {
        return false;
      }

      const { position, direction } = pose;
      const implant: ImplantData = { model: { ...implantModel }, toothNumber, position, direction };
      panoramicService.setPanoramicState(displaySetUID, {
        ...panoramicState,
        implants: [...implants, implant],
      });
      await panoramicService.updateImplantsMask();
    }

    // Like "Move control points", the active tool must not catch the handles
    commandsManager.runCommand('setToolActiveToolbar', { toolName: 'WindowLevel' });
    startImplantEdition(servicesManager, toothNumber, !exists);

    hide();
    return true;
  };

  return (
    <ViewportImplantForm
      onClose={hide}
      implantTeeth={implantTeeth}
      missingTeeth={missingTeeth}
      compact={compact}
      onExpand={onExpand}
      defaultToothNumber={defaultToothNumber}
      onToothChange={onToothChange}
      addImplant={(toothNumber: number) =>
        addImplant(toothNumber, servicesManager.services.panoramicService.getImplantModel())
      }
    />
  );
};

CornerstoneViewportImplantForm.propTypes = {
  hide: PropTypes.func.isRequired,
  servicesManager: PropTypes.object.isRequired,
  commandsManager: PropTypes.object.isRequired,
  compact: PropTypes.bool,
  onExpand: PropTypes.func,
  defaultToothNumber: PropTypes.number,
  onToothChange: PropTypes.func.isRequired,
};

export default CornerstoneViewportImplantForm;
