import { mat4, quat, vec3 } from 'gl-matrix';
import vtkSTLReader from '@kitware/vtk.js/IO/Geometry/STLReader';
import vtkImageData from '@kitware/vtk.js/Common/DataModel/ImageData';
import { Vector3 } from '@kitware/vtk.js/types';
import { Point3 } from '@cornerstonejs/core/types';
import { ImplantData, ImplantModel } from '../../types/Panoramic';
import voxelizeTriangles from './voxelizeTriangles';
import { getImplantModelKey, loadImplantStl } from './catalog';

// Grid used to voxelize the implant STL
const IMPLANT_GRID_SPACING = 0.1; // mm

// Implant volume in its own frame (mm): the axis is +X, from the head to the apex
type ImplantShape = {
  bounds: [Vector3, Vector3];
  contains: (x: number, y: number, z: number) => boolean;
};
const implantShapes: { [key: string]: Promise<ImplantShape> } = {};

// Fallback shape for a model without STL: a cylinder with the model dimensions
const getCylinderShape = ({ diameter, length }: ImplantModel): ImplantShape => {
  const r = diameter / 2;
  return {
    bounds: [
      [0, -r, -r],
      [length, r, r],
    ],
    contains: (x, y, z) => x >= 0 && x <= length && y * y + z * z <= r * r,
  };
};

const computeImplantShape = async (model: ImplantModel): Promise<ImplantShape> => {
  const stl = await loadImplantStl(model);
  if (!stl) {
    return getCylinderShape(model);
  }

  // Voxelize the STL with a fine grid
  const reader = vtkSTLReader.newInstance();
  reader.parse(stl);
  const points = reader.getOutputData().getPoints().getData();
  const s = IMPLANT_GRID_SPACING;
  const { data, dims, origin } = voxelizeTriangles(points, [s, s, s]);

  return {
    bounds: [origin, [origin[0] + dims[0] * s, origin[1] + dims[1] * s, origin[2] + dims[2] * s]],
    contains: (x, y, z) => {
      const i = Math.floor((x - origin[0]) / s);
      const j = Math.floor((y - origin[1]) / s);
      const k = Math.floor((z - origin[2]) / s);
      return (
        i >= 0 &&
        j >= 0 &&
        k >= 0 &&
        i < dims[0] &&
        j < dims[1] &&
        k < dims[2] &&
        data[k * dims[0] * dims[1] + j * dims[0] + i] === 1
      );
    },
  };
};

// Computed once per implant model and size, then cached
const getImplantShape = (model: ImplantModel) => {
  const key = `${getImplantModelKey(model)}/${model.diameter}x${model.length}`;
  implantShapes[key] ??= computeImplantShape(model);
  return implantShapes[key];
};

// Write one implant in the scalar data
const writeImplant = async (
  scalarData: Uint8Array,
  dimensions: Point3,
  imageData: vtkImageData,
  implant: ImplantData,
  segmentIndex: number
) => {
  const shape = await getImplantShape(implant.model);

  // Implant frame -> world: rotate +X onto the direction, then move to the position
  const rotation = quat.rotationTo(quat.create(), [1, 0, 0], implant.direction);
  const localToWorld = mat4.fromRotationTranslation(mat4.create(), rotation, implant.position);
  const indexToLocal = mat4.invert(mat4.create(), localToWorld);
  mat4.multiply(indexToLocal, indexToLocal, imageData.getIndexToWorld());

  // Bounding box in index space
  const [width, height, depth] = dimensions;
  const min = [Infinity, Infinity, Infinity];
  const max = [-Infinity, -Infinity, -Infinity];
  const [low, high] = shape.bounds;
  const world = vec3.create();
  for (const x of [low[0], high[0]]) {
    for (const y of [low[1], high[1]]) {
      for (const z of [low[2], high[2]]) {
        vec3.transformMat4(world, [x, y, z], localToWorld);
        const ijk = imageData.worldToIndex([world[0], world[1], world[2]]);
        for (let c = 0; c < 3; c++) {
          min[c] = Math.min(min[c], ijk[c]);
          max[c] = Math.max(max[c], ijk[c]);
        }
      }
    }
  }
  const [iMin, jMin, kMin] = min.map(v => Math.max(Math.floor(v), 0));
  const iMax = Math.min(Math.ceil(max[0]), width - 1);
  const jMax = Math.min(Math.ceil(max[1]), height - 1);
  const kMax = Math.min(Math.ceil(max[2]), depth - 1);

  const ijk = vec3.create();
  const local = vec3.create();
  for (let k = kMin; k <= kMax; k++) {
    for (let j = jMin; j <= jMax; j++) {
      for (let i = iMin; i <= iMax; i++) {
        vec3.set(ijk, i, j, k);
        vec3.transformMat4(local, ijk, indexToLocal);
        if (shape.contains(local[0], local[1], local[2])) {
          scalarData[k * width * height + j * width + i] = segmentIndex;
        }
      }
    }
  }
};

export { writeImplant };
