import React, { useEffect, useState } from 'react';
import { WediagButton, WediagCollapsible, ProgressLoadingBar } from '@ohif/ui';
import CornerstoneViewportImplantForm from '../../../cornerstone/src/utils/CornerstoneViewportImplantForm';
import ImplantModelSelector from '../../../cornerstone/src/utils/ImplantModelSelector';
import {
  validateImplantEdition,
  cancelImplantEdition,
  deleteEditedImplant,
  recomputeEditedImplant,
  getEditedImplantModel,
  changeEditedImplantModel,
} from '../../../cornerstone/src/utils/implants/implantEdition';
import { getModelFit } from '../../../cornerstone/src/utils/implants';
import { ImplantLimits, ImplantModel } from '../../../cornerstone/src/types/Panoramic';
import { Types as cstTypes } from '@cornerstonejs/tools';
import { generatePanoramic } from './PanoramicUtils/generatePanoramic';
import { ScrollArea } from '@ohif/ui-next';

export default function PanoramicGenerationPanel({
  commandsManager,
  servicesManager,
}: withAppTypes) {
  const { panoramicService, viewportGridService, databaseService } = servicesManager.services;

  const [statusDisplayed, setStatusDisplayed] = useState(panoramicService.isDisplayed());
  // Progress bar for panoramic computation
  const [statusEditing, setStatusEditing] = useState(panoramicService.isEditing());
  const [implantDisplayed, setImplantDisplayed] = useState(panoramicService.isImplantDisplayed());
  // Tooth number of the implant being edited
  const [editedToothNumber, setEditedToothNumber] = useState<number>(
    panoramicService.getEditedToothNumber()
  );
  const isEditingImplant = editedToothNumber !== -1;
  const [implantModel, setImplantModel] = useState(panoramicService.getImplantModel());

  const [implantLimits, setImplantLimits] = useState(panoramicService.getImplantLimits());
  const [analysisReady, setAnalysisReady] = useState(databaseService.isAnalysisReady());

  const [processingPercent, setProcessingPercent] = useState(0);
  const [localComment, setLocalComment] = useState<string>(panoramicService.getComment());
  // Tooth selection of "Add implant", shown small in the panel and enlargeable in a modal
  const [isSelectingTooth, setIsSelectingTooth] = useState(false);

  const [selectedTooth, setSelectedTooth] = useState(-1);

  // Stop tooth selection when implant edition starts
  useEffect(() => {
    if (isEditingImplant) {
      setIsSelectingTooth(false);
    }
  }, [isEditingImplant]);

  useEffect(() => {
    const events = [
      {
        event: panoramicService.EVENTS.PANORAMIC_PROCESSING,
        callback: ({ percent }: { percent: number }) => setProcessingPercent(percent),
      },
      {
        event: panoramicService.EVENTS.STATUS_DISPLAYED_CHANGED,
        callback: ({ displayed }: { displayed: boolean }) => setStatusDisplayed(displayed),
      },
      {
        event: panoramicService.EVENTS.STATUS_EDITING_CHANGED,
        callback: ({ editing }: { editing: boolean }) => setStatusEditing(editing),
      },
      {
        event: panoramicService.EVENTS.IMPLANT_DISPLAYED_CHANGED,
        callback: ({ implantDisplayed }: { implantDisplayed: boolean }) =>
          setImplantDisplayed(implantDisplayed),
      },
      {
        event: panoramicService.EVENTS.EDITED_IMPLANT_CHANGED,
        callback: ({ toothNumber }: { toothNumber: number }) => setEditedToothNumber(toothNumber),
      },
      {
        event: panoramicService.EVENTS.IMPLANT_MODEL_CHANGED,
        callback: ({ implantModel }: { implantModel: ImplantModel }) =>
          setImplantModel(implantModel),
      },
      {
        event: panoramicService.EVENTS.IMPLANT_LIMITS_CHANGED,
        callback: ({ implantLimits }: { implantLimits: ImplantLimits | null }) =>
          setImplantLimits(implantLimits),
      },
    ];

    const subscriptions = events.map(
      ({ event, callback }) => panoramicService.subscribe(event, callback).unsubscribe
    );
    subscriptions.push(
      databaseService.subscribe(databaseService.EVENTS.ANALYSIS_READY_CHANGED, (ready: boolean) =>
        setAnalysisReady(ready)
      ).unsubscribe
    );

    return () => {
      for (const unsub of subscriptions) {
        unsub();
      }
    };
  }, []);

  const deletePanoramicDiseases = () => {
    const { measurementService, toolGroupService } = servicesManager.services;

    //============================= DELETE ALL PREVIOUS DENTASCAN ANNOTATIONS =================//
    const toolGroup = toolGroupService.getToolGroupForViewport('panoramic') as cstTypes.IToolGroup;
    if (!toolGroup) {
      return;
    }
    const diseaseInstance = toolGroup.getToolInstance('Disease');

    const dentascanMeasurements = measurementService.getMeasurements().filter(m => {
      return m.toolName === 'Disease';
    });
    for (const dm of dentascanMeasurements) {
      if (dm.metadata.dentascan) {
        commandsManager.runCommand('removeMeasurement', { uid: dm.uid });
        diseaseInstance.removeDiseaseAnnotation(dm.uid);
      }
    }
  };

  const toggleAnnotation = () => {
    const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
    const panoramicState = panoramicService.getPanoramicState(displaySetUID);
    // controlPoints are at index 0
    panoramicService.showOrHideAnnotations([panoramicState.annotationUIDs[0]], !statusEditing);
    panoramicService.showOrHideAnnotations(panoramicState.annotationUIDs.slice(1), statusEditing);
    // Validating control points coordinates
    if (statusEditing) {
      // Delete diseases
      deletePanoramicDiseases();
      panoramicService.setPanoramicState(displaySetUID, { ...panoramicState, diseases: [] });
      generatePanoramic(servicesManager);
      panoramicService.initDisplay(displaySetUID);
    } else {
      // Change active tool in order to ensure that annotations can be moved
      commandsManager.runCommand('setToolActiveToolbar', { toolName: 'WindowLevel' });
    }
    panoramicService.setEditing(!statusEditing);
  };

  const cancelAnnotation = () => {
    const displaySetUID = viewportGridService.getDisplaySetsUIDsForViewport('axial')[0];
    const panoramicState = panoramicService.getPanoramicState(displaySetUID);
    panoramicService.showOrHideAnnotations([panoramicState.annotationUIDs[0]], false);
    panoramicService.showOrHideAnnotations(panoramicState.annotationUIDs.slice(1), true);
    panoramicService.setEditing(false);
  };

  const toggleHangingProtocol = () => {
    commandsManager.runCommand('toggleHangingProtocol', {
      protocolId: 'panoramicView',
      stageIndex: 1,
    });
  };

  const startToothSelection = () => {
    setSelectedTooth(-1);
    setIsSelectingTooth(true);
    if (!panoramicService.isDisplayed()) {
      commandsManager.runCommand('panoramicView', { reset: false });
    }
  };

  // Large tooth selection, starting from the tooth selected in the panel
  const expandToothSelection = () => {
    servicesManager.services.uiModalService?.show({
      title: 'Select tooth for implant',
      content: CornerstoneViewportImplantForm,
      contentProps: {
        servicesManager,
        commandsManager,
        defaultToothNumber: selectedTooth,
        onToothChange: setSelectedTooth,
      },
      containerClassName:
        'w-[50%] h-[50%] max-w-none grid-rows-[auto_1fr] !bg-grayDarker !bg-opacity-80 rounded-lg shadow-lg',
    });
  };

  // During an implant edition the selector shows the model of the edited implant
  const editedModel = isEditingImplant ? getEditedImplantModel(servicesManager) : undefined;
  const displayedModel = editedModel ?? implantModel;

  // Warnings when the model of the edited implant doesn't fit its limits
  const limitWarnings = [];
  if (editedModel && implantLimits) {
    const { tooWide, tooLong } = getModelFit(editedModel, implantLimits);
    if (tooWide) {
      limitWarnings.push('Model too wide for this site');
    }
    if (tooLong) {
      limitWarnings.push('Model too long for this site');
    }
  }

  const changeImplantModel = async (model: ImplantModel) => {
    await changeEditedImplantModel(servicesManager, model);
    panoramicService.setImplantModel(model);
  };

  return (
    <ScrollArea className="min-h-0 w-full flex-1">
      <div className="flex w-full flex-col items-center space-y-2 pt-2 pr-3">
        <WediagCollapsible
          title={'Panoramic Generation'}
          defaultOpen={true}
        >
          {statusDisplayed && (
            <WediagButton
              buttonCategory="sm"
              variant="bordered"
              onPress={toggleAnnotation}
              className="w-[90%]"
              isDisabled={isEditingImplant}
            >
              {!statusEditing ? 'Move control points' : 'Validate'}
            </WediagButton>
          )}

          {statusDisplayed && statusEditing && (
            <WediagButton
              buttonCategory="sm"
              variant="bordered"
              onPress={cancelAnnotation}
              className="w-[90%]"
            >
              {'Cancel'}
            </WediagButton>
          )}

          <WediagButton
            buttonCategory="sm"
            variant="bordered"
            onPress={toggleHangingProtocol}
            className="w-[90%]"
          >
            {'Dentascan Focus'}
          </WediagButton>

          {processingPercent !== 0 && (
            <div className={'mb-[20px] mt-[10px] w-full'}>
              <p className="text-default w-full text-left">{'Creating panoramic...'}</p>
              <ProgressLoadingBar progress={processingPercent} />
            </div>
          )}
        </WediagCollapsible>

        <WediagCollapsible
          title={'Implantology'}
          defaultOpen={true}
        >
          <ImplantModelSelector
            model={displayedModel}
            onChange={changeImplantModel}
          />

          {isEditingImplant && implantLimits && (
            <div className="text-default w-[90%] text-sm">
              {limitWarnings.length === 0 && <p>{'Model fits this site'}</p>}
              {limitWarnings.map(warning => (
                <p
                  key={warning}
                  className="text-yellow-500"
                >
                  {`! ${warning}`}
                </p>
              ))}
              {implantLimits.limitedByVolume && (
                <p className="opacity-70">{'Length limited by the volume'}</p>
              )}
            </div>
          )}

          {isEditingImplant && (
            <WediagButton
              buttonCategory="sm"
              variant="bordered"
              onPress={() => recomputeEditedImplant(servicesManager)}
              className="w-[90%]"
            >
              {'Recompute implant'}
            </WediagButton>
          )}

          {isSelectingTooth && !isEditingImplant ? (
            <div className="w-[90%]">
              <CornerstoneViewportImplantForm
                compact
                hide={() => setIsSelectingTooth(false)}
                servicesManager={servicesManager}
                commandsManager={commandsManager}
                onExpand={expandToothSelection}
                defaultToothNumber={selectedTooth}
                onToothChange={setSelectedTooth}
              />
            </div>
          ) : (
            <WediagButton
              buttonCategory="sm"
              variant="bordered"
              onPress={() =>
                isEditingImplant ? validateImplantEdition(servicesManager) : startToothSelection()
              }
              className="w-[90%]"
              isDisabled={!analysisReady || statusEditing}
            >
              {!isEditingImplant ? 'Add implant' : `Validate implant ${editedToothNumber}`}
            </WediagButton>
          )}

          {isEditingImplant && (
            <WediagButton
              buttonCategory="sm"
              variant="bordered"
              onPress={() => deleteEditedImplant(servicesManager)}
              className="w-[90%]"
            >
              {`Delete implant ${editedToothNumber}`}
            </WediagButton>
          )}

          {isEditingImplant && (
            <WediagButton
              buttonCategory="sm"
              variant="bordered"
              onPress={() => cancelImplantEdition(servicesManager)}
              className="w-[90%]"
            >
              {'Cancel'}
            </WediagButton>
          )}

          {statusDisplayed && !isEditingImplant && (
            <WediagButton
              buttonCategory="sm"
              variant="bordered"
              onPress={() => panoramicService.toggleImplantDisplay()}
              className="w-[90%]"
            >
              {!implantDisplayed ? 'Display implants' : 'Display diseases'}
            </WediagButton>
          )}
        </WediagCollapsible>

        <WediagCollapsible
          title={'Comment'}
          defaultOpen={true}
        >
          <textarea
            className="border-default text-default placeholder-default bg-background h-40 w-[90%] rounded border-2 p-2"
            placeholder="Enter comment here"
            value={localComment}
            onChange={e => setLocalComment(e.target.value)}
            onBlur={() => panoramicService.setComment(localComment)}
          />
        </WediagCollapsible>
      </div>
    </ScrollArea>
  );
}
