import { Types as cstTypes } from '@cornerstonejs/tools';
import { IVoxelManager } from '@cornerstonejs/core/types';
import { NumberPair } from 'extensions/cornerstone/src/types/Panoramic';

// Teeth in order along each arch (FDI numbering), from the patient's right to left
const UPPER_JAW_TEETH: number[] = [18, 17, 16, 15, 14, 13, 12, 11, 21, 22, 23, 24, 25, 26, 27, 28];
const LOWER_JAW_TEETH: number[] = [48, 47, 46, 45, 44, 43, 42, 41, 31, 32, 33, 34, 35, 36, 37, 38];

const isMandibular = (toothNumber: number) => LOWER_JAW_TEETH.includes(toothNumber);

const isTooth = (toothNumber: number) =>
  UPPER_JAW_TEETH.includes(toothNumber) || LOWER_JAW_TEETH.includes(toothNumber);

// Previous and next teeth on the arch (undefined at the end of the arch or for an unknown tooth)
const getNeighborTeeth = (toothNumber: number) => {
  const arch = isMandibular(toothNumber) ? LOWER_JAW_TEETH : UPPER_JAW_TEETH;
  const index = arch.indexOf(toothNumber);
  if (index === -1) {
    return { previous: undefined, next: undefined };
  }
  return { previous: arch[index - 1], next: arch[index + 1] };
};

// Segment of a tooth in the anatomy segmentation (undefined if the tooth is absent)
const findSegment = (segments: { [segmentIndex: number]: cstTypes.Segment }, toothNumber: number) =>
  Object.values(segments).find(segment => Number(segment?.label) === toothNumber);

// Teeth with at least one voxel in the anatomy segmentation.
const getPresentTeeth = (
  segments: { [segmentIndex: number]: cstTypes.Segment },
  voxelManager: IVoxelManager<number>,
  [minTissueLayer, maxTissueLayer]: NumberPair
) => {
  const scalarData = voxelManager.getCompleteScalarDataArray();
  const [layerWidth, layerHeight] = voxelManager.dimensions;
  const layerSize = layerWidth * layerHeight;

  const foundIndices = new Uint8Array(256);
  const end = Math.min((maxTissueLayer + 1) * layerSize, scalarData.length);
  for (let i = minTissueLayer * layerSize; i < end; i++) {
    foundIndices[scalarData[i]] = 1;
  }

  return [...UPPER_JAW_TEETH, ...LOWER_JAW_TEETH].filter(toothNumber => {
    const segment = findSegment(segments, toothNumber);
    return segment && foundIndices[segment.segmentIndex] === 1;
  });
};

const getMissingTeeth = (presentTeeth: number[]) =>
  [...UPPER_JAW_TEETH, ...LOWER_JAW_TEETH].filter(
    toothNumber => !presentTeeth.includes(toothNumber)
  );

export { isMandibular, isTooth, getNeighborTeeth, findSegment, getPresentTeeth, getMissingTeeth };
