import { ImplantLimits, ImplantModel } from '../../types/Panoramic';
import cylindersCsv from './models/implant_catalog.csv';

// Type of require.context, a bundler (webpack / rspack) function unknown to TypeScript:
// it loads every catalog.json under ./models at build time
declare const require: {
  context: (
    directory: string,
    recursive: boolean,
    regExp: RegExp
  ) => {
    keys: () => string[];
    (key: string): Omit<ImplantModel, 'brand' | 'name' | 'cylinder'>[];
  };
};

// Identifies a model. A cylinder has one model per size, its id lists the SKUs of that size.
// Must stay above getCylinderCatalog, which uses it when the module loads
const getImplantModelKey = (model: ImplantModel) =>
  model.cylinder
    ? `${model.brand}/${model.family}/${model.name}/${model.diameter}x${model.length}`
    : `${model.brand}/${model.id}`;

// Implant models available in the viewer, read from models/<brand>/catalog.json next to their
// STL. The diameter is the maximum one, the length goes from the platform (x = 0 in the STL) to
// the apex
const brandCatalogs = require.context('./models', true, /catalog\.json$/);
const STL_CATALOG: ImplantModel[] = brandCatalogs.keys().flatMap(path => {
  const brand = path.split('/')[1];
  return brandCatalogs(path).map(model => ({
    ...model,
    brand,
    name: model.id.replace(/\d+$/, ''),
    cylinder: false,
  }));
});

// Fields of one CSV line, quoted fields can contain commas and "" for a quote
const parseCsvLine = (line: string) => {
  const fields: string[] = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (quoted && c === '"' && line[i + 1] === '"') {
      field += '"';
      i++;
    } else if (c === '"') {
      quoted = !quoted;
    } else if (c === ',' && !quoted) {
      fields.push(field.trim());
      field = '';
    } else {
      field += c;
    }
  }
  fields.push(field.trim());
  return fields;
};

// Implants without STL, simulated as cylinders, read from models/implant_catalog.csv
const getCylinderCatalog = (): ImplantModel[] => {
  const stlIds = new Set(STL_CATALOG.map(model => model.id));
  const [header, ...lines] = cylindersCsv
    .replace(/^\uFEFF/, '')
    .split(/\r?\n/)
    .filter(line => line.trim());
  const columns = parseCsvLine(header);
  const col = (fields: string[], name: string) => fields[columns.indexOf(name)] ?? '';
  const toNumber = (value: string) => parseFloat(value.replace(',', '.'));

  const models = new Map<string, ImplantModel & { skus: Set<string> }>();
  for (const line of lines) {
    const fields = parseCsvLine(line);
    const sku = col(fields, 'SKU');
    const platform = col(fields, 'plateforme');
    const name =
      [col(fields, 'surface'), platform === 'N/A' ? '' : platform].filter(Boolean).join(' - ') ||
      'Standard';
    const model: ImplantModel = {
      id: '',
      brand: col(fields, 'fabricant'),
      family: col(fields, 'gamme'),
      name,
      diameter: toNumber(col(fields, 'diametre_mm')),
      length: toNumber(col(fields, 'longueur_mm')),
      cylinder: true,
    };
    if (
      !model.brand ||
      !model.family ||
      !(model.diameter > 0) ||
      !(model.length > 0) ||
      stlIds.has(sku)
    ) {
      continue;
    }
    const key = getImplantModelKey(model);
    if (!models.has(key)) {
      models.set(key, { ...model, skus: new Set() });
    }
    if (sku) {
      models.get(key).skus.add(sku);
    }
  }
  return [...models.values()].map(({ skus, ...model }) => ({
    ...model,
    id: [...skus].join(' / '),
  }));
};
const CYLINDER_CATALOG = getCylinderCatalog();

const IMPLANT_CATALOG: ImplantModel[] = [...STL_CATALOG, ...CYLINDER_CATALOG];

// Model selected by default
const DEFAULT_IMPLANT_MODEL_FIELDS: Pick<ImplantModel, 'brand' | 'family' | 'diameter' | 'length'> =
  {
    brand: 'Global D',
    family: 'EVL K',
    diameter: 3.3,
    length: 10,
  };
const DEFAULT_IMPLANT_MODEL =
  IMPLANT_CATALOG.find(model =>
    Object.entries(DEFAULT_IMPLANT_MODEL_FIELDS).every(([field, value]) => model[field] === value)
  ) ?? IMPLANT_CATALOG[0];

// Catalog size of the same model closest to the wanted size, keeping the other dimension.
const getClosestModelSize = (
  model: ImplantModel,
  size: Pick<ImplantModel, 'diameter' | 'length'>,
  keptDimension: 'diameter' | 'length'
) => {
  const resized = keptDimension === 'diameter' ? 'length' : 'diameter';
  const getGap = (other: ImplantModel) => Math.abs(other[resized] - size[resized]);
  const isCloser = (other: ImplantModel, closest: ImplantModel) =>
    getGap(other) < getGap(closest) ||
    (getGap(other) === getGap(closest) && other.name === model.name && closest.name !== model.name);

  return IMPLANT_CATALOG.filter(
    other =>
      other.brand === model.brand &&
      other.family === model.family &&
      other[keptDimension] === model[keptDimension]
  ).reduce((closest, other) => (isCloser(other, closest) ? other : closest), model);
};

// STL of the model, stored in models/<brand>/<id>.stl (axis +X, from the head at x = 0 to the
// apex) and loaded on demand. Undefined if the model has no STL
const loadImplantStl = async ({
  brand,
  id,
  cylinder,
}: ImplantModel): Promise<ArrayBuffer | undefined> => {
  if (cylinder) {
    return undefined;
  }
  try {
    const { default: url } = await import(`./models/${brand}/${id}.stl`);
    const response = await fetch(url);
    return response.ok ? await response.arrayBuffer() : undefined;
  } catch {
    return undefined;
  }
};

// makes it possible to determine whether the model fit the limits.
const getModelFit = (model: ImplantModel, limits: ImplantLimits) => {
  const tooLong = model.length > limits.maxLength;
  const { radiusByDepth, depthStep } = limits;
  const nbDepthsOnModel = Math.min(radiusByDepth.length, Math.floor(model.length / depthStep) + 1);
  const tooWide = radiusByDepth
    .slice(0, nbDepthsOnModel)
    .some(radius => 2 * radius < model.diameter);
  return { tooLong, tooWide };
};

export {
  IMPLANT_CATALOG,
  DEFAULT_IMPLANT_MODEL,
  getImplantModelKey,
  getClosestModelSize,
  loadImplantStl,
  getModelFit,
};
