import { utilities as csUtils } from '@cornerstonejs/core';
import { annotation as cstAnnotation, utilities as cstUtils } from '@cornerstonejs/tools';
import { IVoxelManager, Point3 } from '@cornerstonejs/core/types';
import { ImplantData, ImplantModel, PanoramicState } from '../../types/Panoramic';
import { VolumeData } from '../../types/CornerstoneCacheService';
import { ImplantAnnotation } from '../../tools/ImplantTool';
import {
  dentascanToAxialIndex,
  toPanoramicIndex,
  getImplantSectionPose,
  getViewHandles,
  resizeInView,
  movePositionInPanoramic,
  movePositionInDentascan,
  rotateInPanoramic,
  rotateInDentascan,
} from './implantEditionUtils';
import { computeImplantPose, computeImplantLimits } from './placement';
import { getClosestModelSize, getImplantModelKey } from './catalog';

// Viewports where the edited implant has handles
const IMPLANT_VIEWPORT_IDS = ['panoramic', 'dentascan'];
const ANATOMY_SEG_ID = 'anatomy';
const IMPLANTS_SEG_ID = 'implants';

// Copy of the edited implant or null for a new implant or not editing.
let implantBeforeEdition: ImplantData | null = null;

// -------------------- VIEWPORTS -------------------- //

// Get the CT volume of the axial viewport
const getAxialVolume = (servicesManager: AppTypes.ServicesManager) => {
  const { cornerstoneViewportService } = servicesManager.services;

  return cornerstoneViewportService.getViewportInfo('axial').getViewportData()
    .data[0] as VolumeData;
};

const getViewportImageData = (servicesManager: AppTypes.ServicesManager, viewportId: string) => {
  const { cornerstoneViewportService } = servicesManager.services;

  return cornerstoneViewportService.getCornerstoneViewport(viewportId).getImageData().imageData;
};

// The implant being edited, it is modified in place during the edition
const getEditedImplant = (servicesManager: AppTypes.ServicesManager) => {
  const { panoramicService } = servicesManager.services;

  const { displaySetInstanceUID, volume } = getAxialVolume(servicesManager);
  const panoramicState: PanoramicState = panoramicService.getPanoramicState(displaySetInstanceUID);
  const toothNumber = panoramicService.getEditedToothNumber();
  const implant = panoramicState?.implants.find(implant => implant.toothNumber === toothNumber);

  return { displaySetInstanceUID, volume, panoramicState, implant };
};

// -------------------- ANNOTATIONS -------------------- //

const getImplantAnnotations = () => {
  return cstAnnotation.state
    .getAllAnnotations()
    .filter(annotation => annotation.metadata.toolName === 'Implant') as ImplantAnnotation[];
};

const removeImplantAnnotations = () => {
  for (const annotation of getImplantAnnotations()) {
    cstAnnotation.state.removeAnnotation(annotation.annotationUID);
  }
  cstUtils.triggerAnnotationRenderForViewportIds(IMPLANT_VIEWPORT_IDS);
};

// Implant handles [position, orientation] in the world coordinates of the viewport
const getImplantHandlesPoints = (
  servicesManager: AppTypes.ServicesManager,
  viewportId: string,
  panoramicState: PanoramicState,
  implant: ImplantData
): Point3[] => {
  const { volume } = getAxialVolume(servicesManager);
  const pose = getImplantSectionPose(panoramicState, volume.imageData, implant);
  const imageData = getViewportImageData(servicesManager, viewportId);
  const spacing = imageData.getSpacing();

  const handles = getViewHandles(
    panoramicState,
    pose,
    viewportId === 'panoramic',
    spacing,
    implant.model
  );

  return handles.map(index => imageData.indexToWorld(index) as Point3);
};

// Move the handles of the implant on the panoramic and the dentascan
const updateImplantHandles = (
  servicesManager: AppTypes.ServicesManager,
  panoramicState: PanoramicState,
  implant: ImplantData
) => {
  for (const annotation of getImplantAnnotations()) {
    const { viewportId } = annotation.metadata;
    annotation.data.handles.points = getImplantHandlesPoints(
      servicesManager,
      viewportId,
      panoramicState,
      implant
    );
  }
  cstUtils.triggerAnnotationRenderForViewportIds(IMPLANT_VIEWPORT_IDS);
};

// Create the handles of the edited implant on the panoramic and the dentascan
const createImplantAnnotations = (
  servicesManager: AppTypes.ServicesManager,
  panoramicState: PanoramicState,
  implant: ImplantData
) => {
  const { cornerstoneViewportService } = servicesManager.services;

  for (const viewportId of IMPLANT_VIEWPORT_IDS) {
    const viewport = cornerstoneViewportService.getCornerstoneViewport(viewportId);
    if (!viewport) {
      continue;
    }
    const { viewPlaneNormal, viewUp } = viewport.getCamera();
    const annotation: ImplantAnnotation = {
      invalidated: true,
      highlighted: false,
      isVisible: true,
      isLocked: false,
      metadata: {
        toolName: 'Implant',
        viewportId,
        toothNumber: implant.toothNumber,
        viewPlaneNormal: [...viewPlaneNormal] as Point3,
        viewUp: [...viewUp] as Point3,
        FrameOfReferenceUID: viewport.getFrameOfReferenceUID(),
      },
      data: {
        handles: {
          points: getImplantHandlesPoints(servicesManager, viewportId, panoramicState, implant),
          activeHandleIndex: null,
        },
      },
      annotationUID: csUtils.uuidv4(),
    };
    cstAnnotation.state.addAnnotation(annotation, viewport.element);
  }
  cstUtils.triggerAnnotationRenderForViewportIds(IMPLANT_VIEWPORT_IDS);
};

// -------------------- EDITION -------------------- //

// Display the handles of the edited implant and its dentascan section
const showImplantHandles = (servicesManager: AppTypes.ServicesManager) => {
  const { panoramicService } = servicesManager.services;

  const { displaySetInstanceUID, volume, panoramicState, implant } =
    getEditedImplant(servicesManager);
  if (!implant || !panoramicService.isDisplayed()) {
    return;
  }

  removeImplantAnnotations();
  createImplantAnnotations(servicesManager, panoramicState, implant);

  const { point } = getImplantSectionPose(panoramicState, volume.imageData, implant);
  const [panoramicX] = toPanoramicIndex(point, panoramicState.dentascansDimensions[0]);
  panoramicService.setDentascanIndex(displaySetInstanceUID, panoramicX);
};

const startImplantEdition = (
  servicesManager: AppTypes.ServicesManager,
  toothNumber: number,
  isNewImplant: boolean
) => {
  const { panoramicService } = servicesManager.services;

  panoramicService.setEditedToothNumber(toothNumber);

  const { implant } = getEditedImplant(servicesManager);
  implantBeforeEdition = implant && !isNewImplant ? structuredClone(implant) : null;

  showImplantHandles(servicesManager);
  updateEditedImplantLimits(servicesManager);
};

const stopImplantEdition = (servicesManager: AppTypes.ServicesManager) => {
  const { panoramicService } = servicesManager.services;

  removeImplantAnnotations();
  panoramicService.setEditedToothNumber(-1);
  panoramicService.setImplantLimits(null);
  implantBeforeEdition = null;
};

const validateImplantEdition = (servicesManager: AppTypes.ServicesManager) => {
  const { panoramicService, segmentationService } = servicesManager.services;

  const { displaySetInstanceUID } = getEditedImplant(servicesManager);
  stopImplantEdition(servicesManager);
  panoramicService.saveImplantsInDatabase(displaySetInstanceUID);
  segmentationService.refreshSurfaceRepresentation(IMPLANTS_SEG_ID);
};

// Save the implants in the panoramic state and redraw their mask
const saveImplants = async (servicesManager: AppTypes.ServicesManager, implants: ImplantData[]) => {
  const { panoramicService } = servicesManager.services;

  const { displaySetInstanceUID, panoramicState } = getEditedImplant(servicesManager);
  panoramicService.setPanoramicState(displaySetInstanceUID, { ...panoramicState, implants });
  await panoramicService.updateImplantsMask();
};

// Anatomy segmentation for the placement algorithms
const getAnatomy = (servicesManager: AppTypes.ServicesManager) => {
  const { segmentationService } = servicesManager.services;

  const { segments } = segmentationService.getSegmentation(ANATOMY_SEG_ID);
  const { voxelManager, imageData } = segmentationService.getLabelmapVolume(ANATOMY_SEG_ID);

  return { segments, voxelManager: voxelManager as IVoxelManager<number>, imageData };
};

// Automatic pose { position, direction } of an implant on the tooth, undefined if not found
const getAutomaticPose = (servicesManager: AppTypes.ServicesManager, toothNumber: number) => {
  const { panoramicState } = getEditedImplant(servicesManager);
  return computeImplantPose(
    toothNumber,
    getAnatomy(servicesManager),
    panoramicState.minMaxTissueLayer
  );
};

// Limits of the edited implant at its current pose, null when no implant is edited
const updateEditedImplantLimits = (servicesManager: AppTypes.ServicesManager) => {
  const { panoramicService } = servicesManager.services;

  const { panoramicState, implant } = getEditedImplant(servicesManager);
  const limits =
    implant &&
    computeImplantLimits(
      implant.toothNumber,
      getAnatomy(servicesManager),
      panoramicState.minMaxTissueLayer,
      implant.position,
      implant.direction
    );
  panoramicService.setImplantLimits(limits ?? null);
};

// Cancel: the implant goes back to its pose when the edition started, a new implant is removed
const cancelImplantEdition = async (servicesManager: AppTypes.ServicesManager) => {
  const { panoramicState, implant } = getEditedImplant(servicesManager);
  const savedImplant = implantBeforeEdition;
  stopImplantEdition(servicesManager);
  if (!implant) {
    return;
  }

  const implants = savedImplant
    ? panoramicState.implants.map(other => (other === implant ? savedImplant : other))
    : panoramicState.implants.filter(other => other !== implant);
  await saveImplants(servicesManager, implants);
};

// Delete: the edited implant is removed
const deleteEditedImplant = async (servicesManager: AppTypes.ServicesManager) => {
  const { panoramicService, segmentationService } = servicesManager.services;

  const { displaySetInstanceUID, panoramicState, implant } = getEditedImplant(servicesManager);
  stopImplantEdition(servicesManager);
  if (!implant) {
    return;
  }

  const implants = panoramicState.implants.filter(other => other !== implant);
  await saveImplants(servicesManager, implants);
  panoramicService.saveImplantsInDatabase(displaySetInstanceUID);
  segmentationService.refreshSurfaceRepresentation(IMPLANTS_SEG_ID);
};

// Recompute: the edited implant is placed automatically again, the edition goes on
const recomputeEditedImplant = async (servicesManager: AppTypes.ServicesManager) => {
  const { panoramicState, implant } = getEditedImplant(servicesManager);
  if (!implant) {
    return false;
  }
  const pose = getAutomaticPose(servicesManager, implant.toothNumber);
  if (!pose) {
    return false;
  }

  Object.assign(implant, { position: pose.position, direction: pose.direction });
  await saveImplants(servicesManager, panoramicState.implants);
  showImplantHandles(servicesManager);
  updateEditedImplantLimits(servicesManager);
  return true;
};

// Model of the edited implant, undefined if no implant is edited
const getEditedImplantModel = (servicesManager: AppTypes.ServicesManager) => {
  return getEditedImplant(servicesManager).implant?.model;
};

// Change model: the edited implant keeps its pose, the edition goes on
const changeEditedImplantModel = async (
  servicesManager: AppTypes.ServicesManager,
  model: ImplantModel
) => {
  const { panoramicState, implant } = getEditedImplant(servicesManager);
  if (!implant) {
    return false;
  }

  implant.model = { ...model };
  await saveImplants(servicesManager, panoramicState.implants);
  // The handles depend on the model length
  updateImplantHandles(servicesManager, panoramicState, implant);
  return true;
};

// Handle 0 moves the implant, 1 rotates it, 2 change its length and 3 change its diameter
const moveImplantHandle = (
  servicesManager: AppTypes.ServicesManager,
  annotation: ImplantAnnotation,
  handleIndex: number,
  world: Point3
) => {
  const { panoramicService } = servicesManager.services;

  const { displaySetInstanceUID, volume, panoramicState, implant } =
    getEditedImplant(servicesManager);
  if (!implant) {
    return;
  }

  const { viewportId } = annotation.metadata;
  const pose = getImplantSectionPose(panoramicState, volume.imageData, implant);
  const imageData = getViewportImageData(servicesManager, viewportId);
  const mouse = imageData.worldToIndex(world) as Point3;
  const spacing = imageData.getSpacing();
  const isPanoramic = viewportId === 'panoramic';

  // The panoramic state is updated at the end of the drag
  if (handleIndex === 0) {
    const newPoint = isPanoramic
      ? movePositionInPanoramic(panoramicState, pose, mouse)
      : movePositionInDentascan(panoramicState, pose, mouse);
    const axialIndex = dentascanToAxialIndex(panoramicState, newPoint);
    implant.position = volume.imageData.indexToWorld(axialIndex) as [number, number, number];

    // The central dentascan follows the implant
    if (newPoint.i !== pose.point.i) {
      const [panoramicX] = toPanoramicIndex(newPoint, panoramicState.dentascansDimensions[0]);
      panoramicService.setDentascanIndex(displaySetInstanceUID, panoramicX);
    }
  } else if (handleIndex === 1) {
    const newDirection = isPanoramic
      ? rotateInPanoramic(panoramicState, pose, mouse, spacing)
      : rotateInDentascan(pose, mouse, spacing);
    if (!newDirection) {
      return;
    }
    implant.direction = newDirection;
  } else if (handleIndex > 0 && handleIndex <= 3) {
    const isApex = handleIndex === 2;
    const size = resizeInView(
      panoramicState,
      pose,
      isPanoramic,
      mouse,
      spacing,
      implant.model,
      isApex
    );
    if (!size) {
      return;
    }
    // The implant jumps to an existing size, shown in the panel during the drag
    const model = getClosestModelSize(implant.model, size, isApex ? 'diameter' : 'length');
    if (getImplantModelKey(model) !== getImplantModelKey(implant.model)) {
      implant.model = { ...model };
      panoramicService.setImplantModel(implant.model);
    }
  }

  updateImplantHandles(servicesManager, panoramicState, implant);
};

// Called by ImplantTool when a handle is released
const endImplantDrag = async (servicesManager: AppTypes.ServicesManager) => {
  const { panoramicState } = getEditedImplant(servicesManager);
  await saveImplants(servicesManager, panoramicState.implants);
  updateEditedImplantLimits(servicesManager);
};

export {
  showImplantHandles,
  startImplantEdition,
  stopImplantEdition,
  validateImplantEdition,
  cancelImplantEdition,
  deleteEditedImplant,
  recomputeEditedImplant,
  getEditedImplantModel,
  changeEditedImplantModel,
  getAutomaticPose,
  moveImplantHandle,
  endImplantDrag,
};
