import { vec3 } from 'gl-matrix';
import { Sampler, along } from './volume';
import { NumberPair } from 'extensions/cornerstone/src/types/Panoramic';

// Distances in mm from the tooth surface where the bone is looked for, 2 of these points must be bone
const CREST_PROBES = [0.5, 1, 1.5];
// Max distance in mm from the tooth center to its surface
const SURFACE_SEARCH = 8;

// Depth (from the tooth center along the axis) where the bone starts against the tooth on one
// side, and distance from the axis to the tooth surface
const findSideCrest = (
  sample: Sampler,
  toothIdx: number,
  boneIdx: number,
  center: vec3,
  axis: vec3,
  side: vec3,
  [minDepth, maxDepth]: NumberPair,
  step: number,
  radialStep: number
) => {
  const point = vec3.create();
  for (let depth = minDepth; depth <= maxDepth; depth += step) {
    let surface = -1;
    for (let distance = 0; distance <= SURFACE_SEARCH; distance += radialStep) {
      if (sample(along(point, center, axis, depth, side, distance)) === toothIdx) {
        surface = distance;
      }
    }
    if (surface === -1) {
      continue;
    }
    const nbBone = CREST_PROBES.filter(
      offset => sample(along(point, center, axis, depth, side, surface + offset)) === boneIdx
    ).length;
    if (nbBone >= 2) {
      return { depth, surface };
    }
  }
  return undefined;
};

// Crest depth = average of the mesial (left of tooth) and distal (right of tooth) crests
const findCrestDepth = (
  sample: Sampler,
  toothIdx: number,
  boneIdx: number,
  center: vec3,
  axis: vec3,
  mesioDistal: vec3,
  depthRange: NumberPair,
  step: number,
  radialStep: number
) => {
  const crestDepths = [mesioDistal, vec3.negate(vec3.create(), mesioDistal)]
    .map(
      side =>
        findSideCrest(sample, toothIdx, boneIdx, center, axis, side, depthRange, step, radialStep)
          ?.depth
    )
    .filter(depth => depth !== undefined);
  if (crestDepths.length === 0) {
    return undefined;
  }
  return crestDepths.reduce((sum, depth) => sum + depth, 0) / crestDepths.length;
};

// World point where the bone starts against a neighbor tooth, on its side facing the gap
const findGapCrest = (
  sample: Sampler,
  toothIdx: number,
  boneIdx: number,
  toothPoints: vec3[],
  center: vec3,
  axis: vec3,
  gapSide: vec3,
  step: number,
  radialStep: number
) => {
  const depthRange: NumberPair = [Infinity, -Infinity];
  const offset = vec3.create();
  toothPoints.forEach(point => {
    const depth = vec3.dot(vec3.sub(offset, point, center), axis);
    depthRange[0] = Math.min(depthRange[0], depth);
    depthRange[1] = Math.max(depthRange[1], depth);
  });
  const crest = findSideCrest(
    sample,
    toothIdx,
    boneIdx,
    center,
    axis,
    gapSide,
    depthRange,
    step,
    radialStep
  );
  return crest && along(vec3.create(), center, axis, crest.depth, gapSide, crest.surface);
};

export { findCrestDepth, findGapCrest };
