import { vec3 } from 'gl-matrix';
import vtkImageData from '@kitware/vtk.js/Common/DataModel/ImageData';
import { Point3 } from '@cornerstonejs/core/types';
import { ImplantData, ImplantModel, PanoramicState } from '../../types/Panoramic';

// Distance between the implant apex and its orientation handle (mm)
const ORIENTATION_HANDLE_OFFSET = 3;
// Under this seen fraction of the axis, the apex handle doesn't resize the implant
const MIN_SEEN_AXIS = 0.2;

// i: dentascan index, u: float index along the section normal, layer: dentascan row
type DentascanPoint = { i: number; u: number; layer: number };

// Orthonormal frame of a dentascan section in world coordinates
type SectionFrame = { tangent: vec3; normal: vec3; up: vec3 };

// Implant direction in the section frame (mm)
// alongArch is seen in the panoramic, acrossArch in the dentascan, vertical in both
type ImplantTilt = { alongArch: number; acrossArch: number; vertical: number };

// Implant on its closest dentascan section
type SectionPose = { point: DentascanPoint; frame: SectionFrame; tilt: ImplantTilt };

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);

// -------------------- AXIAL <-> DENTASCAN -------------------- //

// Axial index coordinates -> point on the closest dentascan section
const axialIndexToDentascan = (
  panoramicState: PanoramicState,
  [x, y, z]: Point3
): DentascanPoint => {
  const { minMaxLayer, dentascansDimensions, minPoints, normals } = panoramicState;
  const [nbDentascans, dentascanWidth, dentascanHeight] = dentascansDimensions;

  let closest_i = 0;
  let closest_u = 0;
  let dist = Infinity;

  for (let i = 0; i < nbDentascans; i++) {
    const [minX, minY] = minPoints[i];
    const [vxNormal, vyNormal] = normals[i];
    const norm2 = vxNormal * vxNormal + vyNormal * vyNormal;
    const u = ((x - minX) * vxNormal + (y - minY) * vyNormal) / norm2;
    if (u < 0 || u > dentascanWidth) {
      continue;
    }
    const distance = Math.abs((x - minX) * vyNormal - (y - minY) * vxNormal) / Math.sqrt(norm2);
    if (distance < dist) {
      closest_i = i;
      closest_u = u;
      dist = distance;
    }
  }

  return { i: closest_i, u: closest_u, layer: minMaxLayer[0] + dentascanHeight - 1 - z };
};

// Point on a dentascan section -> axial index coordinates
const dentascanToAxialIndex = (
  panoramicState: PanoramicState,
  { i, u, layer }: DentascanPoint
): Point3 => {
  const { minMaxLayer, dentascansDimensions, minPoints, normals } = panoramicState;
  const dentascanHeight = dentascansDimensions[2];
  const [minX, minY] = minPoints[i];
  const [vxNormal, vyNormal] = normals[i];

  return [minX + u * vxNormal, minY + u * vyNormal, minMaxLayer[0] + dentascanHeight - 1 - layer];
};

// -------------------- IMAGE INDEXES -------------------- //

// The panoramic column x shows the dentascan nbDentascans - 1 - x
const toPanoramicIndex = ({ i, layer }: DentascanPoint, nbDentascans: number): Point3 => {
  return [nbDentascans - 1 - i, layer, 0];
};

// The dentascan pixel x covers [x, x + 1] along the section normal, so its center is u = x + 0.5
const toDentascanIndex = ({ i, u, layer }: DentascanPoint): Point3 => {
  return [u - 0.5, layer, i];
};

// -------------------- IMPLANT POSE -------------------- //

// construct an orthonormal coordinate
const getSectionFrame = (
  panoramicState: PanoramicState,
  imageData: vtkImageData,
  i: number,
  axialIndex: Point3
): SectionFrame => {
  const { minPoints, normals } = panoramicState;
  const nbDentascans = minPoints.length;

  const origin = imageData.indexToWorld(axialIndex);
  const toWorldDirection = ([vx, vy, vz]: Point3) => {
    const [x, y, z] = axialIndex;
    const end = imageData.indexToWorld([x + vx, y + vy, z + vz]);
    const direction = vec3.subtract(vec3.create(), end, origin);
    return vec3.normalize(direction, direction);
  };

  const [vxNormal, vyNormal] = normals[i];
  const normal = toWorldDirection([vxNormal, vyNormal, 0]);
  const up = toWorldDirection([0, 0, 1]);
  const previous = minPoints[Math.max(i - 1, 0)];
  const next = minPoints[Math.min(i + 1, nbDentascans - 1)];
  const tangent = toWorldDirection([previous[0] - next[0], previous[1] - next[1], 0]);
  vec3.scaleAndAdd(tangent, tangent, normal, -vec3.dot(tangent, normal));
  vec3.normalize(tangent, tangent);

  return { tangent, normal, up };
};

// Implant position on its closest dentascan section, and its direction in the section frame
const getImplantSectionPose = (
  panoramicState: PanoramicState,
  axialImageData: vtkImageData,
  implant: ImplantData
): SectionPose => {
  const axialIndex = axialImageData.worldToIndex([...implant.position]) as Point3;
  const point = axialIndexToDentascan(panoramicState, axialIndex);
  const frame = getSectionFrame(panoramicState, axialImageData, point.i, axialIndex);
  const { tangent, normal, up } = frame;
  const tilt = {
    alongArch: vec3.dot(implant.direction, tangent),
    acrossArch: vec3.dot(implant.direction, normal),
    vertical: vec3.dot(implant.direction, up),
  };

  return { point, frame, tilt };
};

// reconstructs the normalized direction
const getDirectionFromTilt = (
  { tangent, normal, up }: SectionFrame,
  { alongArch, acrossArch, vertical }: ImplantTilt
): [number, number, number] => {
  const direction = vec3.create();
  vec3.scaleAndAdd(direction, direction, tangent, alongArch);
  vec3.scaleAndAdd(direction, direction, normal, acrossArch);
  vec3.scaleAndAdd(direction, direction, up, vertical);
  vec3.normalize(direction, direction);

  return [direction[0], direction[1], direction[2]];
};

// -------------------- HANDLES -------------------- //

// Implant position in view index coordinates, and its axis seen in the view (mm, y up)
const getViewAxis = (
  panoramicState: PanoramicState,
  { point, tilt }: SectionPose,
  isPanoramic: boolean
) =>
  isPanoramic
    ? {
        position: toPanoramicIndex(point, panoramicState.dentascansDimensions[0]),
        horizontal: tilt.alongArch,
        vertical: tilt.vertical,
      }
    : { position: toDentascanIndex(point), horizontal: tilt.acrossArch, vertical: tilt.vertical };

// Unit direction perpendicular to the axis seen in the view, horizontal if the axis is not seen
const getViewPerpendicular = (horizontal: number, vertical: number) => {
  const norm = Math.hypot(horizontal, vertical);
  return norm > 1e-6 ? [vertical / norm, -horizontal / norm] : [1, 0];
};

// Handles in view index coordinates, in the order of ImplantAnnotation handles.points
const getViewHandles = (
  panoramicState: PanoramicState,
  pose: SectionPose,
  isPanoramic: boolean,
  [xSpacing, ySpacing]: number[],
  model: ImplantModel
): Point3[] => {
  const { position, horizontal, vertical } = getViewAxis(panoramicState, pose, isPanoramic);
  // Point at (h, v) mm from the position in the view
  const at = (h: number, v: number): Point3 => [
    position[0] + h / xSpacing,
    position[1] - v / ySpacing,
    position[2],
  ];

  const orientationDistance = model.length + ORIENTATION_HANDLE_OFFSET;
  const orientation = at(horizontal * orientationDistance, vertical * orientationDistance);

  const [perpH, perpV] = getViewPerpendicular(horizontal, vertical);
  const radius = model.diameter / 2;
  const apex = at(horizontal * model.length, vertical * model.length);
  const middle = model.length / 2;
  const side = at(horizontal * middle + perpH * radius, vertical * middle + perpV * radius);

  return [position, orientation, apex, side];
};

// -------------------- EDITION -------------------- //

// New implant position for the mouse on the panoramic, the depth in the dentascan section is kept
const movePositionInPanoramic = (
  panoramicState: PanoramicState,
  { point }: SectionPose,
  [x, y]: Point3
): DentascanPoint => {
  const [nbDentascans, , dentascanHeight] = panoramicState.dentascansDimensions;

  return {
    i: clamp(Math.round(nbDentascans - 1 - x), 0, nbDentascans - 1),
    u: point.u,
    layer: clamp(y, 0, dentascanHeight - 1),
  };
};

// New implant position for the mouse on the dentascan
const movePositionInDentascan = (
  panoramicState: PanoramicState,
  { point }: SectionPose,
  [x, y]: Point3
): DentascanPoint => {
  const [, dentascanWidth, dentascanHeight] = panoramicState.dentascansDimensions;

  return {
    i: point.i,
    u: clamp(x + 0.5, 0, dentascanWidth),
    layer: clamp(y, 0, dentascanHeight - 1),
  };
};

// Tilt of the implant axis seen in a view: horizontal component / vertical component
const getViewTilt = (horizontal: number, vertical: number) => {
  return Math.abs(vertical) > 1e-6 ? horizontal / vertical : 0;
};

// The axis follows the mouse in the panoramic, the tilt seen in the dentascan is kept
const rotateInPanoramic = (
  panoramicState: PanoramicState,
  { point, frame, tilt }: SectionPose,
  [x, y]: Point3,
  [xSpacing, ySpacing]: number[]
) => {
  const [positionX, positionY] = toPanoramicIndex(point, panoramicState.dentascansDimensions[0]);
  const alongArch = (x - positionX) * xSpacing;
  const vertical = -(y - positionY) * ySpacing;
  if (!alongArch && !vertical) {
    return undefined;
  }
  const acrossArch = vertical * getViewTilt(tilt.acrossArch, tilt.vertical);

  return getDirectionFromTilt(frame, { alongArch, acrossArch, vertical });
};

// The axis follows the mouse in the dentascan, the tilt seen in the panoramic is kept
const rotateInDentascan = (
  { point, frame, tilt }: SectionPose,
  [x, y]: Point3,
  [xSpacing, ySpacing]: number[]
) => {
  const [positionX, positionY] = toDentascanIndex(point);
  const acrossArch = (x - positionX) * xSpacing;
  const vertical = -(y - positionY) * ySpacing;
  if (!acrossArch && !vertical) {
    return undefined;
  }
  const alongArch = vertical * getViewTilt(tilt.alongArch, tilt.vertical);

  return getDirectionFromTilt(frame, { alongArch, acrossArch, vertical });
};

// Size { diameter, length } of the implant from the mouse on its apex or side handle (mm).
const resizeInView = (
  panoramicState: PanoramicState,
  pose: SectionPose,
  isPanoramic: boolean,
  [x, y]: Point3,
  [xSpacing, ySpacing]: number[],
  model: ImplantModel,
  isApex: boolean
) => {
  const { position, horizontal, vertical } = getViewAxis(panoramicState, pose, isPanoramic);
  const h = (x - position[0]) * xSpacing;
  const v = -(y - position[1]) * ySpacing;

  if (isApex) {
    // The apex is at length * (horizontal, vertical) in the view
    const seenAxis2 = horizontal * horizontal + vertical * vertical;
    if (seenAxis2 < MIN_SEEN_AXIS * MIN_SEEN_AXIS) {
      return undefined;
    }
    return { diameter: model.diameter, length: (h * horizontal + v * vertical) / seenAxis2 };
  }

  const [perpH, perpV] = getViewPerpendicular(horizontal, vertical);
  return { diameter: 2 * Math.abs(h * perpH + v * perpV), length: model.length };
};

export {
  dentascanToAxialIndex,
  toPanoramicIndex,
  getImplantSectionPose,
  getViewHandles,
  resizeInView,
  movePositionInPanoramic,
  movePositionInDentascan,
  rotateInPanoramic,
  rotateInDentascan,
};
