import { vec3 } from 'gl-matrix';
import { Vector3 } from '@kitware/vtk.js/types';
import { findSegment, getNeighborTeeth, getPresentTeeth } from './teeth';
import {
  Anatomy,
  getAxis,
  findStart,
  getImplantPose,
  findBoneIndex,
  scanTeethLayers,
  createSampler,
  along,
  getMean,
  getApicalAxis,
  getRootAxis,
  findNeighborCentroid,
  getMesioDistal,
  findCrestDepth,
  findGapCrest,
  getPerpendicularBasis,
  getObstacles,
  getToothParts,
  getCavities,
  getImplantLimits,
  centerEntry,
  followBone,
} from './placementUtils';
import { NumberPair } from 'extensions/cornerstone/src/types/Panoramic';

// Sampling steps in mm, shared by the crest search and the implant limits
const STEP = 0.25; // along the axis
const RADIAL_STEP = 0.1; // around the axis

type PlacementCase = 'twoNeighbors' | 'replacement' | 'noNeighbor';

// The placement algorithm depends on the teeth present in the anatomy
const getPlacementCase = (presentTeeth: number[], toothNumber: number): PlacementCase => {
  if (presentTeeth.includes(toothNumber)) {
    return 'replacement';
  }
  const { previous, next } = getNeighborTeeth(toothNumber);
  if (presentTeeth.includes(previous) && presentTeeth.includes(next)) {
    return 'twoNeighbors';
  }
  return 'noNeighbor';
};

// -------------------- ALGORITHMS -------------------- //

// Old version, kept for reference (helpers in placementUtils/oldImplant.ts).
// Both neighbor teeth are present: follow their averaged axis down to the bone
const placeOldImplant = (toothNumber: number, anatomy: Anatomy, minMaxTissueLayer: NumberPair) => {
  const { segments, voxelManager, imageData } = anatomy;

  const axis = getAxis(voxelManager, segments, toothNumber, minMaxTissueLayer);
  if (!axis) {
    return undefined;
  }
  const tStart = findStart(voxelManager, toothNumber, axis, minMaxTissueLayer);
  if (tStart === undefined) {
    return undefined;
  }
  return getImplantPose(toothNumber, axis, tStart, imageData);
};

// Both neighbor teeth are present
const placeTwoNeighbors = (
  toothNumber: number,
  anatomy: Anatomy,
  minMaxTissueLayer: NumberPair
) => {
  // Find neighbor's tooth and bone segments
  const { segments } = anatomy;
  const { previous, next } = getNeighborTeeth(toothNumber);
  const previousIdx = findSegment(segments, previous)?.segmentIndex;
  const nextIdx = findSegment(segments, next)?.segmentIndex;
  const boneIdx = findBoneIndex(segments, toothNumber);
  if (previousIdx === undefined || nextIdx === undefined || boneIdx === undefined) {
    return undefined;
  }

  // Read volume
  const { getPoints } = scanTeethLayers(anatomy, [previousIdx, nextIdx], minMaxTissueLayer);
  const previousPoints = getPoints(previousIdx);
  const nextPoints = getPoints(nextIdx);
  if (previousPoints.length < 3 || nextPoints.length < 3) {
    return undefined;
  }
  const sample = createSampler(anatomy);

  // Provisional axis = average of the neighbors axes
  let axis = vec3.add(
    vec3.create(),
    getApicalAxis(previousPoints, toothNumber),
    getApicalAxis(nextPoints, toothNumber)
  );
  vec3.normalize(axis, axis);
  const previousCenter = getMean(previousPoints);
  const nextCenter = getMean(nextPoints);
  const mesioDistal = getMesioDistal(axis, previousCenter, previousCenter, nextCenter);

  // Crest against each neighbor, on its side facing the gap
  const previousCrest = findGapCrest(
    sample,
    previousIdx,
    boneIdx,
    previousPoints,
    previousCenter,
    axis,
    mesioDistal,
    STEP,
    RADIAL_STEP
  );
  const nextCrest = findGapCrest(
    sample,
    nextIdx,
    boneIdx,
    nextPoints,
    nextCenter,
    axis,
    vec3.negate(vec3.create(), mesioDistal),
    STEP,
    RADIAL_STEP
  );
  if (!previousCrest || !nextCrest) {
    return undefined;
  }

  // Entry = average crest depth, and middle of the free space between the tooth surfaces
  let entry = vec3.lerp(vec3.create(), previousCrest, nextCrest, 0.5);

  // Position in the middle of the bone under the crest, then axis following the middle of the bone.
  // Two itheration is sufficient to converge.
  for (let i = 0; i < 2; i++) {
    const sliceMesioDistal = getMesioDistal(axis, previousCenter, previousCenter, nextCenter);
    entry = centerEntry(
      sample,
      previousIdx,
      nextIdx,
      boneIdx,
      entry,
      axis,
      sliceMesioDistal,
      STEP,
      RADIAL_STEP
    );
    axis = followBone(
      sample,
      previousIdx,
      nextIdx,
      boneIdx,
      entry,
      axis,
      sliceMesioDistal,
      STEP,
      RADIAL_STEP
    );
  }

  return {
    position: [entry[0], entry[1], entry[2]] as Vector3,
    direction: [axis[0], axis[1], axis[2]] as Vector3,
  };
};

// The tooth is present: the implant is planned at its place, the segmentation is not modified
const placeReplacement = (toothNumber: number, anatomy: Anatomy, minMaxTissueLayer: NumberPair) => {
  // Find tooth and bone segments
  const { segments } = anatomy;
  const toothIdx = findSegment(segments, toothNumber)?.segmentIndex;
  const boneIdx = findBoneIndex(segments, toothNumber);
  if (toothIdx === undefined || boneIdx === undefined) {
    return undefined;
  }

  // Read volume
  const { getCentroid, getPoints } = scanTeethLayers(anatomy, [toothIdx], minMaxTissueLayer);
  const toothPoints = getPoints(toothIdx);
  if (toothPoints.length === 0) {
    return undefined;
  }
  const sample = createSampler(anatomy);

  // Axis of the whole tooth, only used to find the crest
  const center = getMean(toothPoints);
  const toothAxis = getApicalAxis(toothPoints, toothNumber);
  const depths = toothPoints.map(point =>
    vec3.dot(vec3.sub(vec3.create(), point, center), toothAxis)
  );

  // We deduce the axis of the arcade
  const previous = findNeighborCentroid(toothNumber, 'previous', segments, getCentroid);
  const next = findNeighborCentroid(toothNumber, 'next', segments, getCentroid);
  const mesioDistal = getMesioDistal(toothAxis, center, previous, next);
  if (!mesioDistal) {
    return undefined;
  }

  // Find crest
  // Loop instead of Math.min(...depths): too many arguments for a big tooth
  const depthRange: NumberPair = [Infinity, -Infinity];
  depths.forEach(depth => {
    depthRange[0] = Math.min(depthRange[0], depth);
    depthRange[1] = Math.max(depthRange[1], depth);
  });
  const crestDepth = findCrestDepth(
    sample,
    toothIdx,
    boneIdx,
    center,
    toothAxis,
    mesioDistal,
    depthRange,
    STEP,
    RADIAL_STEP
  );
  if (crestDepth === undefined) {
    return undefined;
  }

  // Entry = center of the tooth section at the crest, direction = axis of the root
  const sectionPoints = toothPoints.filter((_, i) => Math.abs(depths[i] - crestDepth) <= STEP);
  const entry =
    sectionPoints.length > 0
      ? getMean(sectionPoints)
      : along(vec3.create(), center, toothAxis, crestDepth, mesioDistal, 0);
  const rootPoints = toothPoints.filter((_, i) => depths[i] >= crestDepth);
  const axis =
    rootPoints.length >= 3 ? getRootAxis(rootPoints, toothNumber, mesioDistal) : toothAxis;

  return {
    position: [entry[0], entry[1], entry[2]] as Vector3,
    direction: [axis[0], axis[1], axis[2]] as Vector3,
  };
};

// Initial pose { position, direction } in world space, or undefined if no placement was found.
const computeImplantPose = (
  toothNumber: number,
  anatomy: Anatomy,
  minMaxTissueLayer: NumberPair
) => {
  const { segments, voxelManager } = anatomy;
  const presentTeeth = getPresentTeeth(segments, voxelManager, minMaxTissueLayer);

  switch (getPlacementCase(presentTeeth, toothNumber)) {
    case 'twoNeighbors':
      return placeTwoNeighbors(toothNumber, anatomy, minMaxTissueLayer);
    case 'replacement':
      return placeReplacement(toothNumber, anatomy, minMaxTissueLayer);
    case 'noNeighbor':
      // TODO: dedicated algorithm with zero or one neighbor tooth
      return placeOldImplant(toothNumber, anatomy, minMaxTissueLayer);
  }
};

// -------------------- LIMITS -------------------- //

// Limits { maxLength, limitedByVolume, radiusByDepth, depthStep } of an implant at its current pose.
const computeImplantLimits = (
  toothNumber: number,
  anatomy: Anatomy,
  minMaxTissueLayer: NumberPair,
  position: [number, number, number],
  direction: [number, number, number]
) => {
  const { segments, voxelManager } = anatomy;
  const presentTeeth = getPresentTeeth(segments, voxelManager, minMaxTissueLayer);
  const boneIdx = findBoneIndex(segments, toothNumber);
  if (boneIdx === undefined) {
    return undefined;
  }

  // The tooth to replace counts as space available to place the implant
  let isToothPart = new Uint8Array(256);
  if (getPlacementCase(presentTeeth, toothNumber) === 'replacement') {
    const toothIdx = findSegment(segments, toothNumber)?.segmentIndex;
    if (toothIdx === undefined) {
      return undefined;
    }
    isToothPart = getToothParts(segments, toothIdx);
  }

  const axis = vec3.fromValues(...direction);
  return getImplantLimits(
    createSampler(anatomy),
    isToothPart,
    boneIdx,
    getObstacles(segments, toothNumber),
    getCavities(segments),
    vec3.fromValues(...position),
    axis,
    getPerpendicularBasis(axis),
    STEP,
    RADIAL_STEP
  );
};

export { computeImplantPose, computeImplantLimits };
